/* Fleet sign-in sheet (design.md `modal`, the password sign-in every app shares).
 *
 * VENDORED VERBATIM from project-scaffolding. Do NOT edit this file per-app:
 * per-app variation is the three `requestSignIn` options only. Normalized from
 * app-launcher's sign-in card (the look) and voice-transcriber's / grocery's
 * awaitable prompt (the shape).
 *
 * This file builds the one sign-in `<dialog>` itself, so the password input
 * exists nowhere else in an app: the conventions ratchet's
 * `password-input-vendored` rule fails any other one. Pairs with sign-in.css,
 * on the modal, button and select-native recipes.
 *
 * UI only. The component posts `{password}` to the app's own endpoint and hands
 * the returned token to the app; it never reads or writes storage, so each app
 * keeps its own token key and its own server-side checks.
 */

'use strict';

const TITLE = 'Sign in';
const SUBMIT_LABEL = 'Sign in';
const BUSY_LABEL = 'Signing in…';

/* The fixed message set: the same condition reads the same in every app. */
const MESSAGES = {
  wrong: 'Wrong password',
  notSetUp: "Password sign-in isn't set up on this server",
  unreachable: "Can't reach the app",
  lockedOut: (seconds) => (seconds === null
    ? 'Too many attempts — try again later'
    : `Too many attempts — try again in ${seconds} s`),
  failed: (status) => (status ? `Sign-in failed (HTTP ${status})` : 'Sign-in failed — try again'),
};

const MARKUP = `
<div class="detail-card">
  <form class="sign-in-form" novalidate>
    <div class="detail-header">
      <h2 class="sign-in-title" id="signInTitle"><svg class="icon" aria-hidden="true" focusable="false"><use href="#i-lock"></use></svg><span></span></h2>
    </div>
    <p class="sign-in-hint"></p>
    <input class="input-native sign-in-input" type="password" name="password"
           autocomplete="current-password" placeholder="Password" aria-label="Password" required>
    <p class="sign-in-error" role="alert" hidden></p>
    <div class="detail-actions">
      <button type="submit" class="button-primary detail-save-btn sign-in-submit" data-track="sign-in-submit" disabled></button>
    </div>
  </form>
</div>`;

let dialog = null;
let pending = null;

/** Seconds until a retry, from a `Retry-After` value (delta-seconds or an HTTP date); null when unusable. */
function retrySeconds(value) {
  if (!value) return null;
  const trimmed = value.trim();
  if (/^\d+$/.test(trimmed)) return Number(trimmed);
  const at = Date.parse(trimmed);
  return Number.isNaN(at) ? null : Math.max(0, Math.ceil((at - Date.now()) / 1000));
}

function messageFor(res) {
  if (res.status === 401) return MESSAGES.wrong;
  if (res.status === 429) return MESSAGES.lockedOut(retrySeconds(res.headers.get('Retry-After')));
  if (res.status === 503) return MESSAGES.notSetUp;
  return MESSAGES.failed(res.status);
}

function parts() {
  return {
    form: dialog.querySelector('.sign-in-form'),
    input: dialog.querySelector('.sign-in-input'),
    error: dialog.querySelector('.sign-in-error'),
    submit: dialog.querySelector('.sign-in-submit'),
  };
}

function buildDialog() {
  const el = document.createElement('dialog');
  el.className = 'detail-dialog sign-in';
  el.setAttribute('data-track-view', 'sign-in');
  el.setAttribute('aria-labelledby', 'signInTitle');
  el.innerHTML = MARKUP;
  el.querySelector('.sign-in-title span').textContent = TITLE;
  // No × and no Esc: the app cannot be used signed out, so the sheet stays until it succeeds.
  el.addEventListener('cancel', (ev) => ev.preventDefault());
  el.addEventListener('close', () => { if (pending && !el.open) el.showModal(); });
  document.body.appendChild(el);
  return el;
}

function setBusy(busy) {
  const { input, submit } = parts();
  submit.disabled = busy || !input.value;
  submit.textContent = busy ? BUSY_LABEL : SUBMIT_LABEL;
  submit.setAttribute('aria-busy', busy ? 'true' : 'false');
  input.readOnly = busy;
}

function showError(message) {
  const { error, input } = parts();
  error.textContent = message;
  error.hidden = false;
  input.focus();
  input.select();
}

/**
 * Ask for the password and resolve with the token once the server accepts it.
 * While a prompt is open, every further call returns the same promise, so the
 * 401 handler of any number of API calls can await one sign-in.
 *
 * @param {object} opts
 * @param {string} opts.endpoint  the app's login route (e.g. `/api/login`), posted `{password}` as JSON.
 * @param {(token: string) => (void|Promise<void>)} opts.onToken  stores the token the app's own way;
 *        the sheet closes only after it returns.
 * @param {string} [opts.hint]  one line under the title (e.g. "Enter the password to use the launcher.").
 * @returns {Promise<string>} the token.
 */
export function requestSignIn({ endpoint, onToken, hint }) {
  if (pending) return pending;
  if (!endpoint || typeof onToken !== 'function') {
    return Promise.reject(new TypeError('requestSignIn needs an endpoint and an onToken callback'));
  }
  if (!dialog) dialog = buildDialog();
  const { form, input, error } = parts();
  const hintEl = dialog.querySelector('.sign-in-hint');
  hintEl.textContent = hint || '';
  hintEl.hidden = !hint;
  input.value = '';
  error.hidden = true;
  setBusy(false);

  pending = new Promise((resolve) => {
    const onInput = () => { if (!input.readOnly) parts().submit.disabled = !input.value; };
    const onSubmit = async (ev) => {
      ev.preventDefault();
      if (!input.value || input.readOnly) return;
      error.hidden = true;
      setBusy(true);
      let res;
      try {
        res = await fetch(endpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ password: input.value }),
        });
      } catch {
        setBusy(false);
        showError(MESSAGES.unreachable);
        return;
      }
      const body = res.ok ? await res.json().catch(() => null) : null;
      const token = body && typeof body.token === 'string' ? body.token : '';
      if (!token) {
        setBusy(false);
        showError(res.ok ? MESSAGES.failed(res.status) : messageFor(res));
        return;
      }
      try {
        await onToken(token);
      } catch (exc) {
        // The password was right but the app could not keep the token: an app bug, logged for its owner.
        console.warn('sign-in: onToken failed', exc);
        setBusy(false);
        showError(MESSAGES.failed(null));
        return;
      }
      form.removeEventListener('submit', onSubmit);
      input.removeEventListener('input', onInput);
      input.value = '';
      pending = null;
      dialog.close();
      resolve(token);
    };
    form.addEventListener('submit', onSubmit);
    input.addEventListener('input', onInput);
  });
  dialog.showModal();
  input.focus();
  return pending;
}
